// Тикет #6a86f7e9 · 4d0f208d1b1b (реджект rej_1790684508668 от 29.09). Опора: F-43 · S-26, S-10.
// Шаги 2–4 web (копия записи на 3 с раньше через page.route, «תפילות אחרונות» с HH:mm:ss) не переносятся — см. COVERAGE-prayer.md.
// Группа 23.09 старая: чтобы не листать всю историю, она выводится поиском «י״ב» (поиск проверен в PH-01).
import { expect } from '@wdio/globals';
import { byText, byLabel, tapText, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';

describe('История молитв', () => {
  afterEach(async () => { await toHome(); });

  it('PH-02 Записи одной молитвы в одну минуту — с секундами, одиночная — HH:mm (י״ב תשרי · 23 בספט׳) #6a86f7e9 @prod-safe', async () => {
    // 1. Главная → «צפה בהכל» → поиск «י״ב» → группа «י״ב תשרי · 23 בספט׳».
    await scrollToText('צפה בהכל');
    await tapText('צפה בהכל');
    await (await byText('היסטוריית התפילות שלי')).waitForDisplayed({ timeout: 20000 });
    const field = await byLabel('חיפוש');
    await field.clearValue();
    await field.setValue('י״ב');
    await (await byText('י״ב תשרי · 23 בספט׳')).waitForDisplayed({ timeout: 20000 });

    // Одиночная в минуте запись — HH:mm; серия в одну минуту — HH:mm:ss.
    await expect(byLabel('מנחה, י״ב תשרי · 23 בספט׳, 15:12')).toBeDisplayed();
    await expect(byLabel('מנחה, י״ב תשרי · 23 בספט׳, 15:11:14')).toBeDisplayed();
    await expect(byLabel('מנחה, י״ב תשרי · 23 בספט׳, 15:11:12')).toBeDisplayed();
  });
});
